mapper.select:
SELECT BASI.ACCT_SUBJECT_ID prodId, /* 产品代码 */ BASI.ACCT_SUBJECT_NAME finprodName, /* 产品名称 */ SIV.SERIALNO serialNo, /* 业务流水号 */ #{INTER_TYPE_SUBJECTINFO,jdbcType=VARCHAR} interType, /* 对账对象 */ DECODE(SIV.XML_STATUS,null,0,SIV.XML_STATUS) xmlStatus, /* 报文状态 */ SIV.RETURN_TXT as returnTxt /* 接收信息 */ FROM BOK_BOOKSET BB LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = BB.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{INTER_TYPE_SUBJECTINFO,jdbcType=VARCHAR} WHERE BB.BOOKSET_TYPE != #{BOOKSET_TYPE_TEMPLATE,jdbcType=VARCHAR}
AND BASI.ACCT_SUBJECT_ID IN
#{item}
and DECODE(SIV.XML_STATUS,null,0,SIV.XML_STATUS) = #{xmlStatus,jdbcType=VARCHAR}
